-- RN-014/RN-015 (regras-de-negocio/pessoas.md): tabela de referência de Naturezas Jurídicas (CONCLA).
-- Classifica a Pessoa Jurídica como setor público ou privado (RN-015); código não catalogado
-- recusa a importação (RN-014). Mantida manualmente — código novo entra por migration nova.
IF OBJECT_ID(N'dbo.LegalNatures', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.LegalNatures
    (
        Id            UNIQUEIDENTIFIER NOT NULL CONSTRAINT PK_LegalNatures PRIMARY KEY,
        EmissionYear  INT              NOT NULL,
        Code          NVARCHAR(10)     NOT NULL,
        Name          NVARCHAR(150)    NOT NULL,
        IsPrivate     BIT              NOT NULL,
        CreatedAt     DATETIME2        NOT NULL,
        CreatedBy     NVARCHAR(100)    NOT NULL,
        UpdatedAt     DATETIME2        NULL,
        UpdatedBy     NVARCHAR(100)    NULL
    );

    CREATE UNIQUE INDEX IX_LegalNatures_Code ON dbo.LegalNatures (Code);

END
